trans=str.maketrans(dict(zip('абвгдеёзийклмнопрстуфхыэ','abvgdeezijklmnoprstufhye')))
def slug(s):
    for a,b in {'ж':'zh','ц':'ts','ч':'ch','ш':'sh','щ':'shch','ю':'yu','я':'ya','ъ':'','ь':''}.items():s=s.lower().replace(a,b)
    return re.sub('[^a-z0-9]+','-',s.translate(trans)).strip('-')
def clean(s,source):
    old=s
    for a,b in fixes.items():s=s.replace(a,b)
    s=re.sub(r'\s+',' ',s).strip()
    if source==373:s=re.sub(r'\s+26$','',s)
    if s!=old:stats['corrections'].append({'source':source,'before':old,'after':s})
    return s
results=[]
for n,(start,ident,title) in enumerate(chapters):
    end=chapters[n+1][0] if n+1<len(chapters) else 9999
    chapter={'id':ident,'number':n+1,'title':title,'sections':[]}
    sec={'id':'vvedenie','title':title,'level':2,'intro':True,'blocks':[]};chapter['sections'].append(sec)
    used=set()
    for b in raw:
        i=b['source'];text=b['text']
        if not start<i<end:continue
        if re.fullmatch(r'\d+|Раздел \d+\.',text) or text in ('Содержание:','.........'):
            stats['omitted'].append({'source':i,'reason':'page number, running chapter label or graphic punctuation'});text=''
        ishead=b['style'] in ('2','3') or i in headings
        if ishead:
            stitle=custom_titles.get(i,text)
            sid=slug(stitle);sid=sid if sid not in used else sid+'-'+str(i);used.add(sid)
            sec={'id':sid,'title':stitle,'level':headings.get(i,int(b['style']) if b['style'].isdigit() else 2),'source':i,'blocks':[]};chapter['sections'].append(sec)
        if b['type']=='tbl':
            rows=[[clean(v,i) for v in row] for row in b['rows']]
            if len(rows)>1:sec['blocks'].append({'type':'table','title':'Передвижение машин на 1 очко скорости','headers':rows[0],'rows':rows[1:],'sources':[i]})
        elif text and (not ishead or i in preserve_heading_text) and i not in caption_sources:
            text=clean(text,i);kind='bullet' if b['style']=='a5' else 'p'
            prev=sec['blocks'][-1] if sec['blocks'] else None
            if prev and prev['type'] in ('p','bullet') and kind=='p' and text[0].islower() and not re.search('[.!?;:]$',prev['text']):
                prev['text']+=' '+text;prev['sources'].append(i)
            else: sec['blocks'].append({'type':kind,'text':text,'sources':[i]})
        for file in b['images']:
            num=int(re.search(r'\d+',file).group())
            if num in ignored_images:continue
            shutil.copy2(ROOT/'tmp/source/media'/file,media/file)
            figure={'type':'figure','file':file,'caption':labels.get(num,'Иллюстрация из исходных правил.'),'sources':[i]}
            sec['blocks'].append(figure);stats['figures'].append({'file':file,'source':i})
            if num in tables:
                caption,headers,rows=tables[num]
                sec['blocks'].append({'type':'table','title':caption,'headers':headers,'rows':rows,'transcription':True,'sources':[i]})
            if num in extra:sec['blocks'].append({'type':'p','text':extra[num],'transcription':True,'sources':[i]})
        if i in notes:sec['blocks'].append({'type':'note','text':notes[i],'sources':[i]})
        if i==414:sec['blocks'].append({'type':'table','title':'Результат теста брони Д12','headers':['Результат броска','Что происходит'],'rows':[['Д12 ≤ броня','Пилот не пострадал'],['Д12 > броня','Тест выживания Д6']],'derived':True,'sources':[413,414]})
    chapter['sections']=[s for s in chapter['sections'] if s['blocks'] or not s.get('intro')]
    (dest/f'{n+1:02d}-{ident}.json').write_text(json.dumps(chapter,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    results.append(chapter)
